  "update.afterBackupHint": "Завантажує образ і перестворює цей контейнер одразу після успішного резервного копіювання, тож у вас завжди спершу є свіжа точка відновлення. Виконується в час резервного копіювання (резервні копії виконуються одна за одною), а не у фіксований час. Для оновлень за фіксованим розкладом, з урахуванням версії, див. ShipLog.",
