  "update.afterBackupOrphans":
    "Docker залишає образ, на якому контейнер працював раніше, тепер без тегу, і Unraid показує його як осиротілий образ. Це звичайний залишок успішного оновлення, а не слід невдалого, і саме він потрібен для швидкого повернення до попереднього образу. Якщо тримати його не потрібно, перемикач «Видаляти старий образ після оновлення» в розділі «Налаштування, Розклад, Оновлення після резервного копіювання» видаляє замінений образ відразу після оновлення.",
