  "breakdown.title": "Розмір за теками",
  "breakdown.hint": "Що займає місце в найновішій копії, від найбільшого, і скільки з цього остання копія принесла нового чи зміненого. Змінений файл враховується цілком, бо restic не каже, яка його частина змінилася. Розміри — це розміри файлів до дедуплікації та стиснення. BombVault читає їх з індексу репозиторію, не читаючи самих файлів, і оновлює після кожної копії.",
