  // Retention
  "excludes.advisoryImmichDb": "Immich зберігає альбоми, обличчя та дати кожної фотографії в базі даних PostgreSQL, а вона працює в окремому контейнері, не в цьому, тому до цієї резервної копії вона не потрапляє. Відновлення звідси поверне самі знімки, але без усього цього. BombVault знімає дамп контейнера цієї бази даних сам, коли копіює його, тож перевірте, що він є у вашому розкладі.",
  "excludes.advisoryNextcloudDb": "Nextcloud зберігає облікові записи, спільні ресурси та теги в базі даних, яка зазвичай працює в окремому контейнері, тому до цієї резервної копії вона не потрапляє. Файли повернуться, а спільний доступ ні. BombVault знімає дамп контейнера цієї бази даних сам, коли копіює його, тож перевірте, що він є у вашому розкладі.",
