  "rcloneRemote.heading": "Додати місце призначення SMB або WebDAV",
  "rcloneRemote.hint": "Підключається до спільного ресурсу Windows або Samba чи до сервера WebDAV, як-от Nextcloud, без монтування на хості. restic не радить тримати репозиторій на змонтованому спільному ресурсі CIFS, а цей спосіб узагалі обходиться без монтування. Пароль передається rclone, який зберігає його у власному форматі, і ніколи не зберігається у відкритому вигляді. NFS тут не пропонується, бо ані restic, ані rclone його не підтримують: для NFS змонтуйте експорт в Unraid і вкажіть на нього Шлях резервних копій.",
