  "whatsNew.signInMakeDefault": "Зірка позначає облікові дані за замовчуванням, що діють скрізь, де нічого не вибрано. «Зробити типовими» передає зірку іншим.",
  "whatsNew.signInEdit": "«Редагувати» відкриває облікові дані у вікні, де «Перевірити» до збереження пробує їх у кожному місці призначення, яке їх використовує.",
  "whatsNew.gotItCheck": "На кожній кнопці «Зрозуміло» є позначка.",
