  "whatsNew.memoryLimit": "З лімітом пам'яті на одне копіювання велике копіювання сповільнюється, а не обривається через брак пам'яті.",
  "whatsNew.instancesCardLogo": "На кожній картці екземпляра логотип стоїть на тому самому місці й має той самий розмір, на рівні назви.",
  "whatsNew.instancesNetLogos": "На схемі групи кожен BombVault показує логотип із маленьким значком, який відрізняє сервер від телефона.",
