  "whatsNew.instancesNetLabels": "Назви на схемі групи переносяться на наступні рядки, а не обрізаються.",
  "whatsNew.instancesInactive": "Вимкнені сервери й телефони із закритим застосунком зберігають свою картку як Неактивно, з часом, коли їх бачили востаннє, доки ви їх не вилучите.",
  "whatsNew.instancesChecking": "Одразу після запуску BombVault картка показує Перевірка, доки її екземпляр не повернеться, і не виглядає зниклою.",
  "whatsNew.pairingInactive": "Сторінка Спарювання показує вимкнені сервери й телефони із закритим застосунком як Неактивно, з часом, коли їх бачили востаннє.",
  "whatsNew.settingsStorageFlow": "Сторінка налаштувань «Місця призначення» також показує, який розділ у яке місце призначення копіюється.",
  "whatsNew.addOwnRclone": "У «Додати місце призначення» є плитка Rclone для власної конфігурації rclone, куди вставляються remotes з rclone.conf.",
  "whatsNew.cryptPicture": "Малюнок шифрування стежить за своїм перемикачем: запечатані пакети в місці призначення, коли копії шифруються, і читабельні, коли ні.",
  "whatsNew.providerLogos": "У «Додати місце призначення» Amazon S3, Synology C2, Shade, 1Fichier, QingStor, Sia, FileLu, Drime і rclone показують свої логотипи, а кожна плитка під вказівником світиться кольором свого бренду. premiumize.me більше немає в списку, бо він не зберігає резервні копії.",
  "whatsNew.settingsStorageList": "Сторінка налаштувань «Місця призначення» показує всі місця призначення. Клік відкриває одне з них.",
  "whatsNew.offsiteCopies": "Зовнішня копія кожного розділу займає один рядок в одній картці, з перевіркою, реплікацією та налаштуванням у рядку. Усе інше відкривається у вікні.",
  "whatsNew.compressionRow": "Вибір стиснення стоїть поруч зі своїм підписом і займає не більше місця, ніж три його варіанти.",
  "whatsNew.localProtection": "Локальна папка показує картку «Захист від видалення», лише коли на ній є захист, який можна вимкнути.",
