  "whatsNew.signIns": "Спільні хмарні облікові дані й додаткові набори облікових даних стали одним списком, один запис у ньому за замовчуванням. Список стоїть під місцями призначення й показує, які місця використовують який запис.",
  "whatsNew.locationSignIn": "Місце призначення вибирає зі збережених облікових даних, а «Редагувати» відкриває їх у тому самому вікні, що й сторінка налаштувань.",
  "whatsNew.ownFolderMove": "Власна тека розділу може переїхати в одне з ваших місць призначення і переймає його облікові дані й захист. Кілька розділів переїжджають за один крок.",
  "whatsNew.ownFoldersCard": "Віддалене місце призначення показує розділи, які зберігають там свої резервні копії.",
