  "runReason.containersNotBack": "деякі контейнери не запустилися знову",
  "dbdump.toggle": "Дамп бази даних перед кожною резервною копією",
  "dbdump.toggleHint": "BombVault розпізнав цей контейнер як базу даних {engine}. Перед кожною резервною копією він просить у запущеного сервера повний SQL-дамп і складає його як окрему точку відновлення просто в сховище копій, не записуючи файл на ваші диски. Відновлення використовує копію файлів, зроблену після зупинки контейнера; дамп це друга копія, яку можна завантажити або імпортувати. Невдалий дамп ніколи не валить резервну копію, він з'являється як окремий невдалий запуск.",
  "dbdump.toggleHintLabel": "Мітка контейнера bombvault.dbdump вмикає дамп для цієї бази даних {engine}. Перед кожною резервною копією BombVault просить у запущеного сервера повний SQL-дамп і складає його як окрему точку відновлення. Невдалий дамп ніколи не валить резервну копію, він з'являється як окремий невдалий запуск.",
  "dbdump.toggleHintOnlyCopy": "Перед кожною резервною копією BombVault просить у цього запущеного сервера {engine} повний SQL-дамп і складає його як окрему точку відновлення. У цього контейнера дамп це єдина узгоджена копія бази: її тека з даними або копіюється під час роботи сервера, або її немає в жодній копії. Залиште дамп увімкненим. Невдалий дамп ніколи не валить резервну копію, він з'являється як окремий невдалий запуск.",
  "dbdump.toggleHintUnknown": "Перед кожною резервною копією BombVault просить у цього запущеного сервера {engine} повний SQL-дамп і складає його як окрему точку відновлення. Де цей контейнер тримає свою теку з даними, встановити не вдалося, тож невідомо, чи містить копія файлів щось придатне. Дамп це копія, на яку можна покластися. Залиште його увімкненим. Невдалий дамп ніколи не валить резервну копію, він з'являється як окремий невдалий запуск.",
  "dbdump.lookalikeHint": "Цей контейнер схожий на базу даних {engine}, але BombVault не знає його образ напевно. Увімкніть дамп, якщо це вона; якщо потім він не вдасться, образ не дотримується звичних налаштувань і ви можете вимкнути його знову.",
  "dbdump.engineLabel": "Тип бази даних",
  "dbdump.labelOff": "Вимкнено міткою контейнера bombvault.dbdump=false.",
  "dbdump.globalOff": "Автоматичні дампи баз даних вимкнені для всіх контейнерів у Налаштування, Загальні.",
  "dbdump.offConfirmLive": "Вимкнути дамп для цієї бази даних? Її тека з даними копіюється під час роботи сервера, тож без дампа не існує жодної узгодженої копії.",
  "dbdump.offConfirmNone": "Вимкнути дамп для цієї бази даних? Її теки з даними немає в жодній копії, тож без дампа від неї не зберігається нічого.",
  "dbdump.offConfirmUnknown": "Вимкнути дамп для цієї бази даних? BombVault не зміг встановити, де її тека з даними, тож невідомо, чи містить якась копія щось придатне.",
  "dbdump.coverageStopped": "Тека з даними: збережена під час зупиненого контейнера.",
  "dbdump.coverageLive": "Тека з даними: копіюється під час роботи сервера. Дамп це узгоджена копія.",
  "dbdump.coverageNone": "Тека з даними: у жодній копії. Дамп це єдина копія.",
  "dbdump.coverageUnknown": "Тека з даними: встановити не вдалося. Залиште дамп увімкненим.",
  "dbdump.coverageHint": "База даних увесь час пише у свої файли. Копія цих файлів надійна лише тоді, коли сервер зупинений під час її створення, і саме так BombVault робить для тек у копії контейнера. Теки проєкту compose або набору тек копіюються під час роботи сервера, а теки поза appdata не копіюються взагалі. У цих випадках саме з дампа ви відновлюватимете.",
