  "dbdump.damagedBadge": "Пошкоджений",
  "dbdump.damagedHint": "Цей дамп не пройшов перевірок, і прибрати його автоматично не вдалося. Його не можна ні завантажити, ні імпортувати. Вилучіть його.",
