  "dbdump.saveHint": "Записує дамп файлом у вибрану теку на сервері, власник nobody:users, щоб ви могли відкрити його через мережевий ресурс. Файл містить усі таблиці та хеші паролів користувачів бази; тримайте його там, куди дістаєтеся лише ви.",
  "dbdump.saveCancelHint": "Скасування спиняє запис і прибирає незавершений файл.",
  "dbdump.savedTo": "Збережено в {path}",
  "dbdump.import": "Імпорт до свіжої бази даних",
  "dbdump.importConfirm": "Імпортувати цей дамп {engine} {version} до {container}? BombVault зупиняє контейнер, відсуває його теку з даними вбік (вона лишається, нічого не видаляється), запускає контейнер із порожньою текою і імпортує дамп. Застосунки, що користуються цією базою, побачать її стан на час дампа.",
  "dbdump.importConfirmNoVersion": "Імпортувати цей дамп {engine} до {container}? BombVault зупиняє контейнер, відсуває його теку з даними вбік (вона лишається, нічого не видаляється), запускає контейнер із порожньою текою і імпортує дамп. Застосунки, що користуються цією базою, побачать її стан на час дампа.",
  "dbdump.importNoVersion": "Цей дамп не записує версію своєї бази даних. Імпорт не вдасться, якщо сервер не зможе його прочитати.",
  "dbdump.importStops": "one=На час імпорту BombVault зупиняє й {apps}, а потім запускає його знову. Якщо імпорт не вдався вже після початку, старі дані лишаються відкладеними, а застосунок зупиненим.|few=На час імпорту BombVault зупиняє й ці застосунки: {apps}. Потім запускає їх знову. Якщо імпорт не вдався вже після початку, старі дані лишаються відкладеними, а застосунки зупиненими.|many=На час імпорту BombVault зупиняє й ці застосунки: {apps}. Потім запускає їх знову. Якщо імпорт не вдався вже після початку, старі дані лишаються відкладеними, а застосунки зупиненими.|other=На час імпорту BombVault зупиняє й ці застосунки: {apps}. Потім запускає їх знову. Якщо імпорт не вдався вже після початку, старі дані лишаються відкладеними, а застосунки зупиненими.",
  "dbdump.importDone": "Базу даних імпортовано.",
  "dbdump.keptIncluded": "Копія лежить поруч із текою даних, тож будь-яка резервна копія чи репліка теки або набору даних рівнем вище містить її. Видаліть її, коли база даних запрацює.",
  "dbdump.removeKept": "Видалити копію",
  "dbdump.keptRemoved": "Копію видалено.",
  "dbdump.importRefused.busy": "Зараз триває інше резервне копіювання або відновлення. Спробуйте ще раз, коли воно завершиться.",
  "dbdump.importRefused.notRunning": "Спершу запустіть контейнер; імпорту потрібен працюючий сервер.",
  "dbdump.importRefused.engineMismatch": "Цей дамп знято з бази даних іншого типу, ніж той, що працює в контейнері.",
  "dbdump.importRefused.noDataMount": "BombVault не дістається до теки з даними цього контейнера, тож не може безпечно відсунути її вбік. Імпортуйте дамп вручну, як описує аварійний набір.",
  "dbdump.importRefused.version": "Сервер працює з версією {server}, а дамп знято з {dump}. Для цього імпорту візьміть образ із версією {dump} або новішою.",
  "dbdump.importRefused.versionSameMajor": "Сервер працює з версією {server}, а дамп знято з {dump}. MySQL і MariaDB імпортують дамп лише в ту основну версію, з якої його знято, тож для цього імпорту візьміть образ із версією {dump}.",
  "dbdump.importRefused.damaged": "Цей дамп пошкоджений, імпортувати його не можна.",
