  "offsite.wizard.tlsNote": "Цей рецепт використовує звичайний HTTP — у довіреній мережі LAN або VPN це не проблема. Якщо сховище доступне через інтернет, розмістіть rest-server за HTTPS (зворотний проксі з TLS), щоб облікові дані репозиторію не передавалися у відкритому вигляді.",
  "offsite.wizard.password": "Згенерований пароль (збережіть його)",
  "offsite.wizard.passwordInfo": "Одна таємниця у двох виглядах. Відкритий текст вище йде в REST-пароль цього місця призначення, тут на цій машині. Рецепти нижче несуть той самий пароль уже хешованим, у рядку, що дописує в .htpasswd, і цей рядок іде на машину зберігання. Хешувати вам нічого не треба.",
