  "offsite.prune.info": "Цей крок лише повідомляє, що відбувається, він нічого не налаштовує. Чи буде ця копія очищатися, визначають append-only з кроку 4 і значення зберігання в розділі Налаштування, Місця призначення. Щоб усе ж очистити append-only копію, виконайте restic forget --prune на боці місця призначення — або за власним розкладом, або ненадовго піднявши другий REST сервер без append-only, очистивши через нього і знову його вимкнувши.",
