  // Restore from another BombVault repo — Recovery page (#61 task 11)
  "recovery.abTitle": "Імпорт із плагіна Appdata.Backup",
  "recovery.abIntro": "Перетворює архіви, записані плагіном Appdata.Backup, на точки відновлення відповідних контейнерів, кожну з датою, коли плагін її створив. Архіви лише читаються, ніколи не змінюються і не видаляються. Кожен розпаковується поруч із репозиторієм, зберігається в резервну копію, а розпакована копія знову видаляється, тому там потрібне місце для найбільшого архіву.",
