  "recovery.foreignKey": "APP_KEY іншого екземпляра",
  "recovery.foreignKeyHint": "Ключ із 64 символів з аварійного комплекту іншого екземпляра — ваш власний ключ залишається недоторканим.",
  "recovery.foreignCredsIntro": "Це схоже на віддалене сховище, тож потрібні облікові дані бекенду іншого сервера. Вони використовуються лише протягом цього сеансу й ніколи не зберігаються. Ваші власні дані для віддаленого сховища тут навмисно не використовуються повторно: вони пішли б на адресу, яку ви щойно ввели.",
