  "oauth.errorFailed": "Не вдалося перевірити запит. Перезавантажте сторінку, щоб спробувати знову.",
  "mcp.statusOAuthOnly": "Увімкнено: чекаємо, поки клієнт увійде через OAuth",
  "mcp.oauthToggle": "Вхід через OAuth",
  "mcp.oauthHint": "Для ChatGPT, Claude на claude.ai та інших сервісів, які не приймають ключ. Вони відправляють вас на сторінку BombVault, де ви входите зі своїм паролем для входу й дозволяєте їм доступ. Вони звертаються до BombVault зі своїх серверів, тому BombVault має бути доступним з інтернету за публічною адресою нижче, із сертифікатом, якому довіряють браузери. Якщо його вимкнути, усі клієнти вийдуть із системи.",
