  "mcp.setupClaudeAi": "На claude.ai відкрийте Налаштування, Конектори й виберіть Додати власний конектор. Дайте йому ім'я, вставте URL конектора, залиште порожніми ідентифікатор клієнта та секрет OAuth і додайте його. Потім виберіть Під'єднати.",
