  "settings.memoryLabel": "Ліміт пам'яті на одне копіювання (MiB, 0 = немає)",
  "settings.memoryHint": "М'який ліміт пам'яті для кожного процесу резервного копіювання, у MiB. 0 означає відсутність ліміту. Біля ліміту процес звільняє пам'ять частіше, що коштує трохи швидкості, і все одно виходить за ліміт, коли потребує більше. Задайте його помітно нижче за те, що може використовувати контейнер, щоб велике резервне копіювання сповільнювалося, а не завершувалося примусово через нестачу пам'яті.",
