  "relay.instanceCert": "Реле потім працює за адресою /relay/connect на його адресі, за тим самим зворотним проксі та сертифікатом.",
  "relay.instanceCertTip": "Йому не потрібен власний сертифікат. Усе, що робить ваш екземпляр доступним ззовні, достатньо і для реле.",
  "relay.addressLabel": "Адреса вашого реле",
  "relay.addressTip": "Ця адреса стосується лише цього екземпляра. Введіть її на кожному екземплярі, який має бути доступним через ваше реле.",
  "relay.plaintextWarning": "Ця адреса не має TLS, тому ключ реле йде мережею відкритим текстом. Будь-хто на шляху може його прочитати й приєднатися до вашої групи на реле. Він не прочитає, що ваші екземпляри надсилають один одному, але бачитиме, які екземпляри й коли спілкуються. Використовуйте це лише в мережі, якій довіряєте.",
  "relay.diagramRelay": "Реле",
  "relay.diagramYourNetwork": "Ваша мережа",
  "relay.diagramOtherNetwork": "Інша мережа",
  "relay.e2e": "На кожному шляху все зашифровано наскрізно. Хто б не керував реле, проєкт чи ви, нічого з цього прочитати не може.",
  "relay.e2eTip": "Ключ походить із дванадцяти слів і залишається на ваших екземплярах. Реле бачить лише, для якого екземпляра повідомлення, який у нього розмір і коли воно надходить. Це неможливо приховати шифруванням. Якщо це вас турбує, керуйте власним реле.",
