    "BombVault лише читає отриманий репозиторій, тож не полагодить його за вас. Щоб полагодити самостійно, запустіть restic за вказаним вище шляхом із паролем, виведеним з APP_KEY відправного примірника: він лежить у наборі відновлення того примірника, а не цієї машини. Спершу спробуйте `restic repair index`, потім `restic repair snapshots`, якщо знімки лишаються нечитними.",
