  "anomaly.cardHint": "BombVault порівнює кожну резервну копію запису з попередніми й називає те, що не сходиться: набагато більше нових даних, ніж зазвичай, перезапис більшої частини даних, джерело, яке сильно зменшилося або зросло, менший дамп бази даних, копію, яка раптом триває набагато довше, повторювані збої, перевірку відновлення, яка більше не проходить, і диск, що скоро заповниться. Більшості перевірок спершу потрібно 10 копій запису. Запис ZFS перевіряється за наборами даних, тож спорожнілий дочірній набір даних помітний навіть у великому дереві.",
