  "anomaly.settings.title": "Аномалії",
  "anomaly.settings.hint": "Порівнює кожну копію запису з його власною історією і повідомляє про те, що не вписується. Працює у фоні після кожної копії й жодну не сповільнює. Більшість перевірок починається після 10 копій запису; збої, перезапис більшої частини даних і майже порожнє джерело перевіряються від самого початку. Вільне місце відстежується для локальних репозиторіїв і для репозиторіїв rclone, які його повідомляють; на користувацькому ресурсі Unraid це вільне місце всього масиву.",
