  "anomaly.settings.notifyMuted": "Зараз нічого не надсилається: сповіщення вимкнено або не налаштовано жодного каналу.",
  "anomaly.settings.openNotifications": "Відкрити налаштування сповіщень",
  "anomaly.settings.holdToggle": "Зберігати старі копії, коли джерело різко зменшилося або було перезаписане",
  "anomaly.settings.holdHint": "Три знахідки призупиняють видалення старих копій: джерело, яке раптом майже порожнє, джерело, що стало значно меншим, і копія, яка заново зберегла більшу частину даних, як це виглядає після програми-вимагача. Інакше зберігання видаляло б добрі старі копії одну за одною. Поки така аномалія відкрита, зберігаються старі копії лише цього запису (або цього дампу бази даних чи набору даних ZFS); усе інше очищується як зазвичай. Підтвердьте аномалію або позначте її як очікувану, щоб продовжити.",
