  "storage.flow.hint": "Типове значення для кожного розділу. На схемі кожна лінія є перемикачем: клацання по лінії чи точці вмикає або вимикає його. Пунктирні лінії вимкнені. У режимі «Перемикачі» те саме налаштовується кнопками. Перемикач визначає, куди підуть нові резервні копії. Записи, які дотримуються типового значення, одразу переходять разом із ним, тож їхня наступна копія піде в нові місця призначення. Уже збережені копії залишаються там, де лежать, і ви й надалі можете відновити їх звідти. Записи, що вибрали на своїй сторінці власні місця призначення, зберігають їх. Власні правила розділу, наприклад зберігання, стиснення чи окрему адресу, задають на сторінці місця призначення.",
