  "overview.calendar.hint": "Останні 90 днів, по одній клітинці на день. Клацання на дні показує його рядки в журналі в розділі «Історія».",
  "overview.storage.hint": "Скільки місця займає кожен розділ і наскільки добре дані дедуплікуються.",
  "overview.summary.hint": "Найстаріша резервна копія серед усіх розділів, коли запуститься наступна копія і чим закінчилася остання.",
  "overview.stats.hint": "Рахується, як усюди: записи ввімкнених розділів, які досі встановлені. Власний контейнер BombVault записом не є.",
  "overview.coverage.hint": "Усе на цьому сервері, що не охоплене жодною запланованою копією. Вимкнені розділи не враховуються.",
  "overview.coverage.counted": "Рахується, як усюди: записи ввімкнених розділів, які досі встановлені й які ви не виключили. Нижче все, що не охопить наступний запланований запуск, зокрема виключені записи та окремі набори даних.",
  "overview.spike.hint": "До чого BombVault дотягується на хості і що йому потрібно.",
  "overview.customizeHint": "Картку можна перетягувати за смугу, щоб змінити порядок, змінювати її розмір точкою в нижньому куті або ховати непотрібне. Зберігається в цьому браузері.",
