  "whatsNew.overviewHead": "Зелені точки позначають нове. Клацання приховує точку, а всі вони зібрані в розділі Налаштування, Інформація.",
  "whatsNew.overviewCustomize": "Огляд починається з п'яти карток. Решта чекає в «Налаштувати», а кожну картку можна переміщувати, змінювати їй розмір і приховувати.",
  "whatsNew.overviewDecline": "«Не копіювати» прибирає запис із цього списку, коли ви виключаєте його навмисно. Після цього він більше не вважається незахищеним.",
  "whatsNew.overviewInstances": "У застосунку для Android угорі огляду вказано назву екземпляра, на якому ви перебуваєте. Стрілка перед назвою повертає вас до огляду застосунку, де перелічено всі ваші екземпляри.",
  "whatsNew.backupsTiles": "Усе, що копіюється, лежить в одному списку. Плитки обирають тип.",
