  "whatsNew.backupsRow": "Рядок показує один статус, а решта лежить у бульбашці біля назви. Рядки вибирають, як файли: Ctrl+клацання, Shift+клацання або довге натискання.",
  "whatsNew.backupsActions": "Головна дія сторінки пливе внизу праворуч. «Більше» зберігає рідкісні.",
  "whatsNew.entryPage": "Кожен запис має власну сторінку з трьома вкладками: «Резервні копії», «Налаштування» і «Перевірка».",
  "whatsNew.entryDefaults": "Запис дотримується розкладу й місця призначення за замовчуванням, поки не отримає тут власні.",
  "whatsNew.restoreTiles": "«Відновлення» — одна сторінка для всього. Виберіть розділ або знайдіть запис, потім виберіть резервну копію на його часовій шкалі.",
  "whatsNew.restoreWhere": "Одне вікно питає, що відновити і куди. «Поруч з оригіналом» повертає копію й залишає оригінал як є.",
  "whatsNew.restoreMany": "Виберіть кілька записів через Ctrl+клацання, Shift+клацання або довге натискання й відновіть їх разом, один за одним.",
  "whatsNew.restoreEmergency": "Тут починається аварійний майстер. За чотири кроки він повертає сервер, що зник або був налаштований заново.",
  "whatsNew.anomaliesTiles": "Плитки обирають важливість. «Відкрита» або «Закрита» обирає список.",
  "whatsNew.anomaliesRings": "Кільце біля кожного запису показує, наскільки виявлення навчилося відрізняти норму.",
  "whatsNew.storageList": "Локальні й зовнішні місця призначення лежать в одному списку. Кожне місце призначення має власну сторінку.",
  "whatsNew.storageFlow": "3-2-1 у вигляді картинки. Кожна лінія від розділу до місця призначення — перемикач, зокрема Локально, і один клік вмикає або вимикає його. Розділ показує, скільки його записів копіюється в інше місце.",
  "whatsNew.locationKeep": "Зберігання буває «Коротко», «Помірно», «Довго» або з вашими значеннями. Часова шкала показує, які резервні копії залишає правило.",
  "whatsNew.locationMove": "«Перемістити» переносить копію розділу в інше місце призначення разом з усією історією.",
  "whatsNew.instancesPair": "Екземпляри спарюються дванадцятьма словами. Потім кожен показує свої ролі плитками.",
  "whatsNew.instancesPhones": "Телефони, спарені через застосунок для Android, отримують окрему картку поруч з екземплярами.",
  "whatsNew.settingsTiles": "Налаштування — це чотирнадцять плиток. Натисніть / або Ctrl+K, щоб шукати по всіх, зокрема за колишніми назвами сторінок.",
  "whatsNew.settingsPin": "Місця призначення й Екземпляри — плитки налаштувань. Цей перемикач закріплює їх на бічній панелі.",
  "whatsNew.settingsWeek": "Тиждень у вигляді стрічки, з кожним запланованим запуском від понеділка до неділі.",
  "whatsNew.pairingSteps": "Три картки показують, як працює спарювання. Під ними реле має чотири форми, і в кожної своя картинка.",
  "whatsNew.settingsVersion": "Інформація містить «Версія», «Довідка» і «Про застосунок». «Версія» перелічує BombVault, GlimStone, restic і rclone. Її кнопка «Нове» відкриває список змін, а коли ви побачите всі, примітки до випуску.",
